#!/usr/bin/env python3
"""Brick 4 frontend for chat_test.html: the 10-minute first win replaces the 3-step setup.

Usage (run in /root/e5-ai-coach):
  python3 patch_brick4_frontend.py --check   dry run: verify every anchor, write nothing
  python3 patch_brick4_frontend.py           apply (backup: chat_test.html.bak-brick4)

Requires Sprint 1.5 A+B frontend. Refuses to run twice.
This file contains no angle brackets or ampersands: they are written as escapes.
"""
import os, shutil, sys

PATH = "chat_test.html"
MARK = "BRICK 4: FIRST WIN"
NEEDS = "SPRINT 1.5 A+B"
NEEDS_MSG = "Sprint 1.5 A+B is not applied. Run patch_sprint15_ab.py first."
BACKUP = PATH + ".bak-brick4"
COMPILE = False

EDITS = [
    ("Brick 4 core before boot",
     "// ===== boot =====",
     "// ===== BRICK 4: FIRST WIN (10-minute first task: offer, 3 outcomes, price, guarantee) =====\nconst FW_TASK='p1_t1';\nconst FW_WHERE_OPTS=[['youtube','YouTube or short videos'],['dms','DMs (Instagram, WhatsApp, LinkedIn)'],['community','A community (Skool, Discord, Whop)'],['email','An email list']];\nconst FW_HOURS_OPTS=[['1-3','1 to 3 hours'],['4-7','4 to 7 hours'],['8+','8 hours or more']];\nconst FW_FROM_TRAFFIC={content:'youtube',outbound:'dms',community:'community',email:'email'};\nconst FW_REASONS={offline:'You are offline. Reconnect and try again.',signed_out:'Your session expired. Sign in with Whop again.',rate_limited:'You have used your AI requests for now. Wait a minute and try again, or write it yourself.',ai_unavailable:'The AI could not draft right now. Try again, or write it yourself.',ai_bad_output:'The AI draft came back incomplete. Try again, or write it yourself.',already_done:'This task is already complete.',wrong_task:'Your current task has changed. Refresh and try again.',invalid:'Some answers are missing. Check the fields and try again.',db_unavailable:'Your first win could not be saved. Your text is still here. Try again in a moment.',timeout:'This took too long. Try again.',network:'Could not reach the server. Check your connection and try again.'};\nlet _fwBusy=false,_fwToken=0,_fwErr='';\nObject.assign(SETUP_MOVE,{t:'Get your first win',w:'Answer 4 quick questions. Your coach drafts your offer, you edit it, and your first task is done. About 10 minutes.',cta:'Start (about 10 min)',fw:'First win'});\nObject.assign(UI_AR,{'Get your first win':'\u0627\u062d\u0635\u0644 \u0639\u0644\u0649 \u0623\u0648\u0644 \u0625\u0646\u062c\u0627\u0632 \u0644\u0643','Question':'\u0633\u0624\u0627\u0644','Next':'\u0627\u0644\u062a\u0627\u0644\u064a','Back':'\u0631\u062c\u0648\u0639','Do this later':'\u0644\u0627\u062d\u0642\u0627\u064b','Save my first win':'\u0627\u062d\u0641\u0638 \u0623\u0648\u0644 \u0625\u0646\u062c\u0627\u0632','Redraft':'\u0623\u0639\u062f \u0627\u0644\u0635\u064a\u0627\u063a\u0629','Write it myself':'\u0633\u0623\u0643\u062a\u0628\u0647 \u0628\u0646\u0641\u0633\u064a','Try again':'\u062d\u0627\u0648\u0644 \u0645\u062c\u062f\u062f\u0627\u064b','Your first task':'\u0645\u0647\u0645\u062a\u0643 \u0627\u0644\u0623\u0648\u0644\u0649'});\nfunction fwState(){if(!isObj(S.main.firstWin))S.main.firstWin={step:1,mode:'full',sell:'',who:'',where:'',hours:'',draft:null,draftFor:''};return S.main.firstWin;}\nfunction fwEligible(id){\n if(String(id)!==FW_TASK)return false;\n const j=S.main.journey;if(!isObj(j))return true;\n const done=(Array.isArray(j.tasks_completed)?j.tasks_completed:[]).map(String);if(done.indexOf(FW_TASK)!==-1)return false;\n if(isObj(j.current_task)){if(String(j.current_task.id)!==FW_TASK)return false;}\n return true;\n}\nfunction fwReason(d){if(!isObj(d))return 'Something went wrong. Try again.';if(d.reason==='invalid'){if(d.detail)return String(d.detail);}return FW_REASONS[String(d.reason||'')]||'Something went wrong. Try again.';}\nasync function fwPost(url,body){\n if(navigator.onLine===false)return {ok:false,reason:'offline'};\n const ctl=new AbortController(),t=setTimeout(function(){ctl.abort();},120000);\n try{\n  const r=await fetch(url,{method:'POST',credentials:'same-origin',headers:jsonHeaders(),body:JSON.stringify(body),signal:ctl.signal});\n  if(!r.ok)return {ok:false,reason:r.status===401?'signed_out':r.status===429?'rate_limited':'network',status:r.status};\n  const d=await r.json();return isObj(d)?d:{ok:false,reason:'network'};\n }catch(e){return {ok:false,reason:e.name==='AbortError'?'timeout':'network'};}\n finally{clearTimeout(t);}\n}\nfunction fwAnswers(){const f=fwState();const a={sell:String(f.sell||''),who:String(f.who||'')};if(f.where)a.where=f.where;if(f.hours)a.hours=f.hours;return a;}\nfunction fwStatus(msg){const s=$('#formStatus');if(s){s.textContent=msg;s.className='callout bad';}}\nfunction fwChoices(k,opts,cur){return '\x3cdiv class=\"chips\" role=\"group\"\x3e'+opts.map(function(o){return '\x3cbutton type=\"button\" class=\"chip'+(cur===o[0]?' on':'')+'\" data-act=\"fw-pick\" data-k=\"'+k+'\" data-v=\"'+esc(o[0])+'\" aria-pressed=\"'+(cur===o[0])+'\"\x3e'+esc(o[1])+'\x3c/button\x3e';}).join('')+'\x3c/div\x3e';}\nfunction fwReadDraft(){return {offer:val('fwOffer'),outcomes:[0,1,2].map(function(i){return val('fwOut'+i);}),price:val('fwPrice'),guarantee:val('fwGuarantee')};}\nfunction fwCheck(d){\n if(d.offer.length\x3c15)return 'Write your offer in at least 15 characters.';\n if(d.outcomes.some(function(x){return !x;}))return 'Fill in all 3 results your customer gets.';\n if(!d.price)return 'Add a price. A guess is fine; you can change it later.';\n if(!d.guarantee)return 'Add a guarantee, even a simple one.';\n return '';\n}\nfunction fwShow(step){\n const f=fwState();f.step=step;save();\n const total=f.mode==='task'?2:4;\n const q=function(n,title,hint){return '\x3cspan class=\"eyebrow\"\x3e'+esc(tx('Question'))+' '+n+' '+esc(tx('of'))+' '+total+'\x3c/span\x3e\x3ch3 style=\"margin:4px 0 0;font-size:18px\"\x3e'+esc(title)+'\x3c/h3\x3e'+(hint?'\x3cp class=\"muted\"\x3e'+esc(hint)+'\x3c/p\x3e':'');};\n const later='\x3cbutton class=\"btn btn-ghost\" data-act=\"modal-close\"\x3e'+esc(tx('Do this later'))+'\x3c/button\x3e';\n const back='\x3cbutton class=\"btn btn-ghost\" data-act=\"fw-back\"\x3e'+esc(tx('Back'))+'\x3c/button\x3e';\n const next='\x3cbutton class=\"btn btn-primary\" data-act=\"fw-next\"\x3e'+esc(tx('Next'))+' '+ic('arrow')+'\x3c/button\x3e';\n const eyebrow='\x3cspan class=\"eyebrow\"\x3e'+ic('spark',13)+' '+esc(tx('Your first task'))+' \u00b7 '+esc('Define Core Offer \x26 Value Stack')+'\x3c/span\x3e';\n let body='',footer='';\n if(step===1){body=q(1,'What do you sell, or want to sell?','One or two sentences. Rough is fine.')+inputField('What you sell','fwSell',f.sell,{area:true,rows:3,max:300});footer=later+next;}\n else if(step===2){body=q(2,'Who is it for?','Describe the person you help, in plain words.')+inputField('Who it is for','fwWho',f.who,{area:true,rows:3,max:300});footer=(f.mode==='task'?later:back)+next;}\n else if(step===3){body=q(3,'Where is your audience?','Pick the place where you can reach people most easily today.')+fwChoices('where',FW_WHERE_OPTS,f.where);footer=back+next;}\n else if(step===4){body=q(4,'How many hours a week do you have?','Be honest. Your plan will fit this.')+fwChoices('hours',FW_HOURS_OPTS,f.hours);footer=back+next;}\n else if(!isObj(f.draft)){\n  if(_fwErr){body=eyebrow+'\x3cdiv class=\"callout warn\"\x3e\x3cspan\x3e'+esc(_fwErr)+'\x3c/span\x3e\x3c/div\x3e';footer=back+'\x3cbutton class=\"btn\" data-act=\"fw-manual\"\x3e'+esc(tx('Write it myself'))+'\x3c/button\x3e\x3cbutton class=\"btn btn-primary\" data-act=\"fw-redraft\"\x3e'+esc(tx('Try again'))+'\x3c/button\x3e';}\n  else{body=eyebrow+'\x3ch3 style=\"margin:4px 0 0;font-size:18px\"\x3eYour coach is drafting your offer\u2026\x3c/h3\x3e\x3cp class=\"muted\"\x3eThis usually takes 10 to 30 seconds.\x3c/p\x3e\x3cdiv class=\"skel\"\x3e\x3ci style=\"width:70%\"\x3e\x3c/i\x3e\x3ci\x3e\x3c/i\x3e\x3ci style=\"width:85%\"\x3e\x3c/i\x3e\x3ci style=\"width:40%\"\x3e\x3c/i\x3e\x3c/div\x3e';footer=back;}\n }else{\n  const d=f.draft,o=Array.isArray(d.outcomes)?d.outcomes:[];\n  body=eyebrow+'\x3ch3 style=\"margin:4px 0 0;font-size:18px\"\x3eEdit your offer, then save\x3c/h3\x3e\x3cp class=\"muted\"\x3eYour coach drafted all four parts this task asks for. Change anything. Nothing is saved until you click Save.\x3c/p\x3e'\n   +inputField('Your offer in one sentence','fwOffer',d.offer||'',{area:true,rows:2,max:280})\n   +'\x3cdiv class=\"field\"\x3e\x3cspan class=\"lab\"\x3e3 results your customer gets\x3c/span\x3e'+[0,1,2].map(function(i){return '\x3cinput id=\"fwOut'+i+'\" maxlength=\"200\" aria-label=\"Result '+(i+1)+'\" value=\"'+esc(o[i]||'')+'\"\x3e';}).join('')+'\x3c/div\x3e'\n   +inputField('Price','fwPrice',d.price||'',{max:60})\n   +inputField('Guarantee','fwGuarantee',d.guarantee||'',{area:true,rows:2,max:280});\n  footer=back+'\x3cbutton class=\"btn\" data-act=\"fw-redraft\"\x3e'+esc(tx('Redraft'))+'\x3c/button\x3e\x3cbutton class=\"btn btn-primary\" data-act=\"fw-save\"\x3e'+esc(tx('Save my first win'))+' '+ic('check')+'\x3c/button\x3e';\n }\n modalForm(tx('Get your first win'),body,footer);\n if(step===5){if(!isObj(f.draft)){if(!_fwErr)fwDraft();}}\n}\nasync function fwDraft(){\n const tok=++_fwToken;\n const d=await fwPost('/api/first-win/draft',{answers:fwAnswers()});\n if(tok!==_fwToken)return;if(!$('#modal').classList.contains('on'))return;\n const f=fwState();if(f.step!==5)return;\n if(d.ok===true){if(isObj(d.draft)){f.draft=d.draft;f.draftFor=JSON.stringify(fwAnswers());save();fwShow(5);return;}}\n _fwErr=fwReason(d);fwShow(5);\n}\nfunction openFirstWin(mode){\n try{requireAccount();}catch(e){toast(e.message);return;}\n const f=fwState();f.mode=mode==='task'?'task':'full';\n if(!String(f.sell||'').trim())f.sell=String(S.dna.offer||S.dna.niche||'');\n if(!String(f.who||'').trim())f.who=String(S.dna.avatar||'');\n if(!f.where)f.where=FW_FROM_TRAFFIC[String((S.main.business||{}).primary_traffic_source||'')]||'';\n if(!f.hours){const h=String((S.main.onboarding||{}).hours||'');if(['1-3','4-7','8+'].indexOf(h)!==-1)f.hours=h;}\n _fwErr='';let step=1;\n if(f.mode==='task'){if(String(f.sell).trim()){if(String(f.who).trim())step=5;}}\n if(isObj(f.draft))step=5;\n fwShow(step);\n}\nfunction fwApplyLocal(d){\n const f=fwState();S.dna.offer=d.offer;\n if(!String(S.dna.niche||'').trim())S.dna.niche=f.sell;\n if(f.who)S.dna.avatar=f.who;\n if(!num(S.dna.price)){const p=num(String(d.price).replace(/[^0-9.]/g,''));if(p)S.dna.price=p;}\n S.main.needsOnboarding=false;if(f.hours)S.main.onboarding.hours=f.hours;\n addActivity('First task done: your offer is saved');S.main.firstWin=null;save();\n}\nACT['fw-pick']=function(el){const k=el.dataset.k;if(['where','hours'].indexOf(k)===-1)return;const f=fwState();f[k]=el.dataset.v;fwShow(f.step);};\nACT['fw-next']=function(){\n const f=fwState(),s=f.step;\n if(s===1){const v=val('fwSell');if(v.length\x3c3){fwStatus('Tell us what you sell, even roughly.');return;}f.sell=v;}\n if(s===2){const v=val('fwWho');if(v.length\x3c3){fwStatus('Describe who it is for, even roughly.');return;}f.who=v;}\n if(s===3){if(!f.where){fwStatus('Pick one option.');return;}}\n if(s===4){if(!f.hours){fwStatus('Pick one option.');return;}}\n track('onboarding_answered',{step:s,flow:'first_win',mode:f.mode});\n let n=s+1;if(f.mode==='task'){if(s===2)n=5;}\n if(n===5){_fwErr='';if(JSON.stringify(fwAnswers())!==f.draftFor)f.draft=null;}\n fwShow(n);\n};\nACT['fw-back']=function(){\n const f=fwState(),s=f.step;\n if(s===1)f.sell=val('fwSell');if(s===2)f.who=val('fwWho');\n if(s===5){if($('#fwOffer'))f.draft=fwReadDraft();_fwToken++;_fwErr='';}\n let n=s-1;if(s===5)n=f.mode==='task'?2:4;\n fwShow(Math.max(1,n));\n};\nACT['fw-redraft']=function(){const f=fwState();f.draft=null;_fwErr='';fwShow(5);};\nACT['fw-manual']=function(){const f=fwState();f.draft={offer:'',outcomes:['','',''],price:'',guarantee:''};f.draftFor=JSON.stringify(fwAnswers());_fwErr='';fwShow(5);};\nACT['fw-save']=function(el){\n if(_fwBusy)return;const f=fwState();const d=fwReadDraft();f.draft=d;save();\n const err=fwCheck(d);if(err){fwStatus(err);return;}\n _fwBusy=true;const old=el.innerHTML;el.disabled=true;el.textContent='Saving\u2026';const answers=fwAnswers(),mode=f.mode;\n return fwPost('/api/first-win',{current_task_id:FW_TASK,offer:d.offer,outcomes:d.outcomes,price:d.price,guarantee:d.guarantee,answers:answers}).then(async function(r){\n  if(r.ok!==true){\n   if(r.reason==='already_done'){S.main.firstWin=null;save();closeModal();toast(FW_REASONS.already_done);await refreshAccount(true);return;}\n   fwStatus(fwReason(r));return;\n  }\n  fwApplyLocal(d);\n  track('first_creation_saved',{field:'first_win'});\n  track('onboarding_answered',{step:'first_win_saved',flow:'first_win',mode:mode,hours:String(answers.hours||''),traffic:String(answers.where||'')});\n  closeModal();celebrate();toast('Task 1 done. Your offer is saved, and your next move is ready.');\n  await refreshAccount(true);go(todayHref());\n }).catch(function(e){fwStatus((e\x26\x26e.message)||'Something went wrong. Try again.');})\n .finally(function(){_fwBusy=false;if(el.isConnected){el.disabled=false;el.innerHTML=old;}});\n};\n// Setup now opens the first-win flow. The old 3-step setup stays in Settings (\"Review coach setup\").\nACT.onboard=function(){openFirstWin('full');};\nACT['onboard-classic']=function(){onboardingModal(1);};\n// \"Start this task\" on Define Core Offer opens the edit card instead of Coach (while p1_t1 is open).\nconst _fwOrigStartTask=ACT['start-task'];\nACT['start-task']=function(el,e){\n const id=String(el.dataset.id||el.dataset.v||'');\n if(fwEligible(id)){track('task_started',{task_id:FW_TASK,task_name:'Define Core Offer \x26 Value Stack',from:String(view),via:evTakeVia(),flow:'first_win'});openFirstWin('task');return;}\n return _fwOrigStartTask(el,e);\n};\n// ===== end BRICK 4 core =====\n\n// ===== boot ====="),
    ("Settings keeps the classic setup",
     "data-act=\"onboard\"\x3eReview coach setup\x3c/button\x3e",
     "data-act=\"onboard-classic\"\x3eReview coach setup\x3c/button\x3e"),
    ("Command Center setup callout text",
     "Personalize your coach in three steps.",
     "Get your first win in about 10 minutes."),
]


def main():
    check = "--check" in sys.argv
    if not os.path.exists(PATH):
        print("ABORTED: " + PATH + " not found in " + os.getcwd())
        sys.exit(1)
    src = open(PATH, encoding="utf-8").read()
    if MARK in src:
        print("ABORTED: this patch is already applied. Nothing written.")
        sys.exit(1)
    if NEEDS not in src:
        print("ABORTED: " + NEEDS_MSG)
        sys.exit(1)
    bad = []
    for name, old, new in EDITS:
        n = src.count(old)
        if n != 1:
            bad.append(name + " (found " + str(n) + " times, expected 1)")
    if bad:
        print("ABORTED: anchors do not match. Nothing written.")
        for b in bad:
            print("  - " + b)
        sys.exit(1)
    out = src
    for name, old, new in EDITS:
        out = out.replace(old, new, 1)
    if MARK not in out:
        print("ABORTED: self-check failed. Nothing written.")
        sys.exit(1)
    if COMPILE:
        try:
            compile(out, PATH, "exec")
        except SyntaxError as e:
            print("ABORTED: patched file would not compile: " + str(e) + ". Nothing written.")
            sys.exit(1)
    if check:
        print("CHECK OK: all " + str(len(EDITS)) + " anchors found exactly once" + (" and the result compiles" if COMPILE else "") + ". Nothing written.")
        return
    shutil.copyfile(PATH, BACKUP)
    open(PATH, "w", encoding="utf-8").write(out)
    print("PATCHED: " + str(len(EDITS)) + " edit(s) applied. Backup: " + BACKUP)
    print("Next: docker compose down, then docker compose up -d --build" + ("" if COMPILE else ", then purge Cloudflare for /app"))


if __name__ == "__main__":
    main()
